// Color-only migration from the app's own styles. Layout and photographs stay intact.
// The file order follows app/layout.tsx. Run after editing source styles.
import fs from "node:fs";
import path from "node:path";
import postcss from "postcss";
const root = path.resolve(import.meta.dirname, "..");
const scope = 'html[data-theme="light"]';
const files = ["sport-profile", "career", "extensions", "globals", "brand-mark", "mobile-app", "social", "subscription", "events", "trust", "community", "agenda", "appearance"];
const output = postcss.parse(`
/* Generated by scripts/build-light-theme.mjs. Do not edit directly. */
${scope} {
  color-scheme: light;
  --app-canvas: #f5f7f4; --app-panel: #ffffff; --app-subtle: #edf1eb;
  --app-tint: #eff5e7; --app-ink: #17211d; --app-muted: #52614e;
  --app-accent-ink: #486319; --app-line: #c9d3c4; --app-danger: #a72f2f;
  --background: var(--app-canvas); --foreground: var(--app-ink);
  --card: var(--app-panel); --primary: #d1f94c; --primary-foreground: #17200d;
  --border: var(--app-line); --muted: var(--app-subtle); --muted-foreground: var(--app-muted);
  --secondary: var(--app-subtle); --input: var(--app-line);
  --ring: var(--app-accent-ink); --destructive: var(--app-danger);
  --color-secondary: var(--app-subtle); --color-muted: var(--app-subtle);
  --color-muted-foreground: var(--app-muted); --color-border: var(--app-line);
  --color-input: var(--app-line); --color-ring: var(--app-accent-ink);
  --color-destructive: var(--app-danger);
}
`);
const photographic = /\.(auth-editorial|welcome-photos|photo-strip|profile-cover|change-photo|opportunity-cover|save-opportunity)(?![\w-])/;
function mapColor(hex, prop, selector) {
  let value = hex.slice(1);
  if (value.length < 5) value = [...value].map(c => c + c).join("");
  const [r,g,b,a] = [0,2,4,6].map((offset,i) => i===3 && value.length===6 ? 255 : parseInt(value.slice(offset,offset+2),16));
  const bright = (r+g+b)/3, max=Math.max(r,g,b), min=Math.min(r,g,b);
  const lime = g>r && g>b*1.5 && g>150;
  const red = r>g*1.2 && r>b*1.2;
  const token = name => `var(--app-${name})`;
  if (/^(color|fill|stroke|text-decoration-color)$/.test(prop)) {
    if (lime) return token("accent-ink");
    if (red && bright>85) return token("danger");
    if (bright<90) return hex; // Retain dark ink on bright action buttons.
    return token(bright>205 ? "ink" : "muted");
  }
  if (/^(border|outline|column-rule)/.test(prop)) return token(lime ? "accent-ink" : red ? "danger" : "line");
  if (/^background/.test(prop)) {
    if (lime) return hex;
    if (red) return "#fff0ee";
    if (a<240 && max-min<15 && bright>230) return "#17211d0a";
    if (max>200) return hex;
    if (/\bbody\b|\.mobile-app-frame\b|\.save-bar\b/.test(selector)) return token("canvas");
    if (g>r+4 && g>b+4) return token("tint");
    return token(bright>35 ? "subtle" : "panel");
  }
  if (prop==="box-shadow") return "#17211d12";
  if (prop==="scrollbar-color") return token("line");
  return hex;
}
for (const file of files) {
  const tree=postcss.parse(fs.readFileSync(path.join(root,`app/${file}.css`),"utf8"));
  tree.walkComments(c=>c.remove());
  tree.walkAtRules(rule=>{
    if (["import","theme","custom-variant"].includes(rule.name) || /keyframes/.test(rule.name)) rule.remove();
  });
  tree.walkRules(rule=>{
    rule.selectors=rule.selectors.filter(s=>!photographic.test(s) && ![":root",".dark"].includes(s)).map(s => s==="html" ? scope : s.startsWith("html ") ? `${scope}${s.slice(4)}` : `${scope} ${s}`);
    if (!rule.selector.trim()) {rule.remove();return;}
    rule.walkDecls(decl=>{
      if (!/^(color|background|border|outline|fill|stroke|box-shadow|text-decoration-color|scrollbar-color)/.test(decl.prop)) {decl.remove();return;}
      const original=decl.value;
      let value=original.replace(/#[a-f\d]{3,8}\b/gi,hex=>mapColor(hex,decl.prop,rule.selector));
      if (decl.prop==="color") value=value.replace(/var\(--primary\)/g,"var(--app-accent-ink)").replace(/^white$/,"var(--app-ink)");
      if (/^(outline|border)/.test(decl.prop)) value=value.replace(/var\(--primary\)/g,"var(--app-accent-ink)");
      if (value===original) decl.remove(); else decl.value=value;
    });
    if (!rule.nodes.length) rule.remove();
  });
  tree.walkAtRules(rule=>{if (!rule.nodes?.length) rule.remove();});
  output.append(tree.nodes);
}
output.append(postcss.parse(`
/* Portal, native control and photographic exceptions. */
${scope} :focus-visible { outline-color: var(--app-accent-ink); }
${scope} .mobile-app-frame { background: var(--app-canvas); }
${scope} .bottom-nav { background: #fffffff5; }
${scope} .profile-layout > .app-header { background: #f5f7f4f5; }
${scope} [data-slot="dialog-content"] { background: var(--app-panel); color: var(--app-ink); }
${scope} [data-slot="dialog-overlay"] { background: #17211d66; }
${scope} input::placeholder, ${scope} textarea::placeholder { color: #667461; opacity: 1; }
${scope} .profile-cover, ${scope} .opportunity-cover, ${scope} .welcome-photos figcaption,
${scope} .photo-strip span, ${scope} .change-photo { color: #f1f2eb; }
${scope} .auth-editorial { color: #f1f2eb; --primary: #d1f94c; }
${scope} .unified-calendar, ${scope} .agenda-event-list, ${scope} .agenda-actions,
${scope} .agenda-discover, ${scope} .agenda-tools {
  --border: var(--app-line); --muted: var(--app-subtle); --muted-foreground: var(--app-muted);
}
${scope} .agenda-dot.match { background: #547719; }
${scope} .agenda-dot.professional { background: #365bac; }
${scope} .agenda-dot.spectator { background: #a85c23; }
`).nodes);
const css=output.toString()+"\n";
const destination=path.join(root,"app/light.css");
if (process.argv.includes("--check")) {
  if (fs.readFileSync(destination,"utf8")!==css) throw Error("Light theme is stale. Run npm run theme:build.");
  console.log("Light theme is up to date.");
} else {
  fs.writeFileSync(destination,css);
  console.log("Generated mobile light theme.");
}
